<template><button :class="['thumb-button',{active:localHasThumb}]" :disabled="!userStore.isLoggedIn||isPending" :title="title" @click.stop="toggle"><svg viewBox="0 0 24 24" :fill="localHasThumb?'currentColor':'none'"><path d="M7.5 10.2 11.2 4c.8-1.3 2.8-.7 2.7.8l-.3 3.2h4a2.3 2.3 0 0 1 2.2 3l-2.1 7a2.3 2.3 0 0 1-2.2 1.6h-8V10.2ZM3.5 10h4v10h-4V10Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><span>{{formatNumber(count)}}</span></button></template>
<script setup>
import { computed } from 'vue';import { useUserStore } from '../stores/user';import { useThumbStore } from '../stores/thumb';import { formatNumber } from '../utils';
const props=defineProps({blogId:{type:[Number,String],required:true},count:{type:Number,default:0},hasThumb:Boolean});const userStore=useUserStore(),thumbStore=useThumbStore();const localHasThumb=computed(()=>props.hasThumb||thumbStore.hasThumb(props.blogId));const isPending=computed(()=>thumbStore.isPending(props.blogId));const title=computed(()=>!userStore.isLoggedIn?'登录后点赞':localHasThumb.value?'取消点赞':'点赞');async function toggle(){if(!userStore.isLoggedIn||isPending.value)return;localHasThumb.value?await thumbStore.undoThumb(props.blogId):await thumbStore.doThumb(props.blogId);}
</script>
<style scoped>.thumb-button{display:inline-flex;height:36px;min-width:68px;align-items:center;justify-content:center;gap:7px;border:1px solid #e2e8f0;border-radius:999px;background:white;color:#64748b;font-size:13px;font-weight:800;transition:.2s}.thumb-button:hover:not(:disabled){border-color:#5eead4;color:#0f766e;transform:translateY(-1px)}.thumb-button.active{border-color:#99f6e4;background:#f0fdfa;color:#0f766e}.thumb-button svg{width:17px}</style>
